MATCH (ta:TerroristAttack)
WHERE
  EXISTS {
    MATCH (ta)-[:employs]->(w:Weapon)
    WHERE any(a IN w.aliases WHERE a CONTAINS 'grenade launcher')
  }
  OR
  EXISTS {
    MATCH (ta)-[:occursIn]->(c:Country)
    WHERE any(a IN c.aliases WHERE a CONTAINS 'Russia')
  }
RETURN count(DISTINCT ta) AS attackCount;

MATCH (att:TerroristAttack)-[:employs]->(wep:Weapon)
WHERE toLower(wep.name) CONTAINS "bomb"
RETURN max(toInteger(substring(att.date, 0, 4))) AS latestYear;

MATCH (ta:TerroristAttack)-[:employs]->(w:Weapon)
WHERE w.name IN ['Shoulder Fired Missile','Rocket Propelled Grenade']
RETURN DISTINCT ta.name;

MATCH (t:TerroristAttack)-[:employs]->(w:Weapon), (t)-[:targets]->(tar:Target)
WHERE toLower(w.name) CONTAINS 'car bomb' AND toLower(tar.name) CONTAINS 'linwood islamic centre'
RETURN t.name AS attack_name, t.number_of_deaths AS death_toll;
